from typing import List, Tuple

class Flow:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v, w):
        if u not in self.graph:
            self.graph[u] = {}
        if v not in self.graph:
            self.graph[v] = {}
        self.graph[u][v] = w
        self.graph[v][u] = 0  # initial reverse edge weight is 0

    def bfs(self, s, t, parent):
        visited = {node: False for node in self.graph}
        queue = [(s, float('inf'))]

        while queue:
            u, flow = queue.pop(0)
            visited[u] = True
            for v in self.graph[u]:
                if not visited[v] and self.graph[u][v] > 0:
                    queue.append((v, min(flow, self.graph[u][v])))
                    parent[v] = u
                    if v == t:
                        return True
        return False

    def ford_fulkerson(self, s, t):
        parent = {node: None for node in self.graph}
        max_flow = 0

        while self.bfs(s, t, parent):
            path_flow = float('inf')
            v = t
            while v!= s:
                u = parent[v]
                path_flow = min(path_flow, self.graph[u][v])
                v = parent[v]
            max_flow += path_flow
            v = t
            while v!= s:
                u = parent[v]
                self.graph[u][v] -= path_flow
                self.graph[v][u] += path_flow
                v = parent[v]
        return max_flow

def f(N: int, M: int, s: int, t: int, edges: List[Tuple[int, int, int, int]]):
    graph = Flow()
    for u, v, _, w in edges:
        graph.add_edge(u, v, w)
    max_flow = 0
    for i in range(s, t+1):
        max_flow += graph.ford_fulkerson(i, t)
    return max_flow

